    btn.addEventListener('click', () => { const on = btn.getAttribute('aria-pressed') !== 'true'; btn.setAttribute('aria-pressed', String(on)); btn.setAttribute('aria-label', on ? 'Stop' : 'Play'); show(on ? 'STOP' : 'PLAY'); });
